const S = 100;
const S2 = S / 2;

const CLRS = ["#c6878f", "#b79d94", "#969696", "#67697c", "#253d5b"];

function setup() {
  const D = max(windowWidth, windowHeight);
  createCanvas(windowWidth, windowHeight); // D, D
	describe("triangles grid with some empty spots and altering color from given blue-grey-red palette")
  frameRate(3);
}

function draw() {
  background("darkred");
	stroke("darkred")
	strokeWeight(S/25);
  // noStroke();

	let oddRow = true;
  for (let y = S2; y < height - S; y += S) {
		oddRow = !oddRow
		let xo = oddRow ? 0 : S2;
		// console.log(xo)
		let oddCol = true;
    for (let x = S + xo; x < width - S; x += S2) {
			oddCol = !oddCol
      const n = noise(x, y, frameCount * 0.01);
      if (n < 0.4 || n > 0.6) continue;

      const ci = ~~(constrain(map(n, 0.4, 0.6, 0, 1, true), 0, 1) * CLRS.length)
      fill(CLRS[ci]);

      if (oddCol) {
        triangle(x - S2, y, x + S2, y, x, y + S);
      } else {
        triangle(x, y, x + S2, y + S, x - S2, y + S);
      }
    }
  }

}
